QIcon icon(const QString& name, const QColor& color) {
  const QString svgRaw = iconPaths().value(name);
  if (svgRaw.isEmpty()) return {};
  QString svg = svgRaw;
  const QString stroke = color.isValid()
      ? QStringLiteral("#%1").arg(color.rgb() & 0xFFFFFF, 6, 16, QLatin1Char('0'))
      : QStringLiteral("#a8a29a");
  svg.replace(QStringLiteral("currentColor"), stroke);
  const QSvgRenderer renderer(svg.toUtf8());
  if (!renderer.isValid()) return {};
  // Plain devicePixelRatio(1) pixmap: QIcon downscaling stays correct on
  // fractional display scales (a hardcoded dpr breaks icon selection there).
  // 64px source keeps 11-16px targets crisp.
  QPixmap pm(64, 64);
  pm.fill(Qt::transparent);
  QPainter p(&pm);
  p.setRenderHints(QPainter::Antialiasing | QPainter::SmoothPixmapTransform);
  const_cast<QSvgRenderer&>(renderer).render(&p, QRectF(0, 0, 64, 64));
  p.end();
  QIcon ic;
  ic.addPixmap(pm);
  return ic;
}

